    out = []
    for row in rows:
        if row.get("status") == "paid" and row.get("amount", 0) > config.min_amount:
            row["tier"] = "gold" if row["amount"] > config.gold_amount else "silver"
            out.append(row)
    return sorted(out, key=lambda x: (-x["amount"], x["id"]))
